"use client";

import { createContext, forwardRef, useContext, useEffect, useRef, type ButtonHTMLAttributes, type DialogHTMLAttributes, type HTMLAttributes, type ReactNode } from "react";

type DialogContextValue = { dialog: React.RefObject<HTMLDialogElement | null>; open: boolean; onOpenChange: (open: boolean) => void };
const DialogContext = createContext<DialogContextValue | null>(null);
function useDialog() { const value = useContext(DialogContext); if (!value) throw new Error("Dialog components must be used inside Dialog."); return value; }
export function Dialog({ open, onOpenChange, children }: { open: boolean; onOpenChange: (open: boolean) => void; children: ReactNode }) { const dialog = useRef<HTMLDialogElement>(null); useEffect(() => { const node = dialog.current; if (!node) return; if (open && !node.open) node.showModal(); if (!open && node.open) node.close(); }, [open]); return <DialogContext.Provider value={{ dialog, open, onOpenChange }}>{children}</DialogContext.Provider>; }
export function DialogTrigger({ onClick, ...props }: ButtonHTMLAttributes<HTMLButtonElement>) { const dialog = useDialog(); return <button type="button" onClick={(event) => { dialog.onOpenChange(true); onClick?.(event); }} {...props} />; }
export function DialogContent({ className = "", onCancel, onClick, ...props }: DialogHTMLAttributes<HTMLDialogElement>) { const dialog = useDialog(); return <dialog ref={dialog.dialog} className={`co-w-[min(32rem,calc(100%-2rem))] co-rounded-xl co-border co-border-black/20 co-bg-white co-p-6 co-text-black co-shadow-xl backdrop:co-bg-black/55 ${className}`.trim()} onCancel={(event) => { dialog.onOpenChange(false); onCancel?.(event); }} onClose={() => dialog.onOpenChange(false)} onClick={(event) => { if (event.target === event.currentTarget) dialog.onOpenChange(false); onClick?.(event); }} {...props} />; }
export function DialogHeader({ className = "", ...props }: HTMLAttributes<HTMLDivElement>) { return <div className={`co-flex co-flex-col co-gap-2 ${className}`.trim()} {...props} />; }
export const DialogTitle = forwardRef<HTMLHeadingElement, HTMLAttributes<HTMLHeadingElement>>(({ className = "", ...props }, ref) => <h2 ref={ref} className={`co-text-lg co-font-semibold ${className}`.trim()} {...props} />);
export function DialogDescription({ className = "", ...props }: HTMLAttributes<HTMLParagraphElement>) { return <p className={`co-text-sm co-text-black/60 ${className}`.trim()} {...props} />; }
export function DialogFooter({ className = "", ...props }: HTMLAttributes<HTMLDivElement>) { return <div className={`co-mt-6 co-flex co-justify-end co-gap-2 ${className}`.trim()} {...props} />; }
export function DialogClose({ onClick, ...props }: ButtonHTMLAttributes<HTMLButtonElement>) { const dialog = useDialog(); return <button type="button" onClick={(event) => { dialog.onOpenChange(false); onClick?.(event); }} {...props} />; }
DialogTitle.displayName = "DialogTitle";
